    {
      "label": "H4: Power‑grid cross‑talk with delayed settling of resonator electronics",
      "probability": 0.15,
      "rationale": "A transient voltage dip or surge could immediately perturb the pendulum_lab electronics and, after capacitive or inductive lag in the resonator_obs power supply, produce a delayed effect visible only in the resonator readings.",
      "evidenceFor": ["crosscheck"],
